MERGE `{{params.project_name}}.semantics_central.FinancingLoans` final
USING (
{{range_query}}
) staging
ON final.loan_id = staging.loan_id
WHEN MATCHED THEN
UPDATE SET
final.loan_id = staging.loan_id,
final.financing_customer_id = staging.financing_customer_id,
final.contract_id = staging.contract_id,
final.car_id = staging.car_id,
final.status = staging.status,
final.amount = staging.amount,
final.amount_usd = staging.amount_usd,
final.fees = staging.fees,
final.fee_loan = staging.fee_loan,
final.fee_loan_usd = staging.fee_loan_usd,
final.due_at = staging.due_at,
final.settled_at = staging.settled_at,
final.disbursed_at = staging.disbursed_at ,
final.created_at = staging.created_at,
final.updated_at = staging.updated_at,
final.deleted_at = staging.deleted_at,
final.created_by_name = staging.created_by_name,
final.created_by_id = staging.created_by_id,
final.updated_by_name = staging.updated_by_name, 
final.updated_by_id = staging.updated_by_id,
final.deleted_by_name = staging.deleted_by_name, 
final.deleted_by_id = staging.deleted_by_id,
final.penalty = staging.penalty,
final.penalty_usd = staging.penalty_usd,
final.sale_price = staging.sale_price,
final.sale_price_usd = staging.sale_price_usd,
final.paid_interest = staging.paid_interest,
final.paid_interest_usd = staging.paid_interest_usd,
final.accrued_interest = staging.accrued_interest,
final.accrued_interest_usd = staging.accrued_interest_usd,
final.amount_due = staging.amount_due,
final.amount_due_usd = staging.amount_due_usd,
final.car_data = staging.car_data,
final.country_id = staging.country_id
WHEN NOT MATCHED THEN
INSERT (
loan_id,
financing_customer_id,
contract_id,
car_id,
status,
amount,
amount_usd,
fees,
fee_loan,
fee_loan_usd,
due_at,
settled_at,
disbursed_at,
created_at,
updated_at,
deleted_at,
created_by_name,
created_by_id,
updated_by_name, 
updated_by_id,
deleted_by_name, 
deleted_by_id,
penalty,
penalty_usd,
sale_price,
sale_price_usd,
paid_interest,
paid_interest_usd,
accrued_interest,
accrued_interest_usd,
amount_due,
amount_due_usd,
car_data,
country_id
) VALUES (
staging.loan_id,
staging.financing_customer_id,
staging.contract_id,
staging.car_id,
staging.status,
staging.amount,
staging.amount_usd,
staging.fees,
staging.fee_loan,
staging.fee_loan_usd,
staging.due_at,
staging.settled_at,
staging.disbursed_at ,
staging.created_at,
staging.updated_at,
staging.deleted_at,
staging.created_by_name,
staging.created_by_id,
staging.updated_by_name, 
staging.updated_by_id,
staging.deleted_by_name, 
staging.deleted_by_id,
staging.penalty,
staging.penalty_usd,
staging.sale_price,
staging.sale_price_usd,
staging.paid_interest,
staging.paid_interest_usd,
staging.accrued_interest,
staging.accrued_interest_usd,
staging.amount_due,
staging.amount_due_usd,
staging.car_data,
staging.country_id
)